/// <summary>
/// Initializes the default values
/// </summary>
void initValue()
{
    next initValue();

    this.AVARUMIsPriceAutoGenerated = NoYes::No;
}

/// <summary>
/// Initializes the PriceDiscTable from a PriceDiscAdmTrans
/// </summary>
/// <param name = "tmpPriceDiscAdm">The PriceDiscAdmTrans record.</param>
void initFromPriceDiscAdm_AVA(PriceDiscAdmTrans tmpPriceDiscAdm)
{
    this.initFromPriceDiscAdm(tmpPriceDiscAdm);                                    

    this.DisregardLeadTime = tmpPriceDiscAdm.DisregardLeadTime;
}
